using Godot;
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
public partial class NewGameFrontEnd
{
 const int UnitCancelCheckpoints=16;
 TroopDispatch CurrentCancel()=>game!.Session.DiagnosticSnapshot().NewMilitary!.Cancellation!.Dispatches.Single();
 async Task UnitCancelStep(int n){await Frame();var s=game!.Session;bool moving=FlowCase=="cancel-moving"||FlowCase.StartsWith("cancelnotice-"),late=FlowCase=="cancel-late";
  if(n==1){var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());game.ExerciseMilitaryLine(new(a.X+20000,a.Y),new(a.X+20000,a.Y+12000));game.Advance(ArmyEnd()+1);}
  if(n==2){if(!moving)game.ChooseMilitary(NewMilitaryAction.Recall);game.ChooseMilitary(NewMilitaryAction.Handoff);game.ChooseMilitary(NewMilitaryAction.Withdraw);}
  if(n==3){game.Advance(Math.Max(PersonalEnd(),moving?s.Seconds:ArmyEnd())+1);game.Press("military-frame");}
  if(n==4)game.ChooseMilitary(NewMilitaryAction.RemoteRecall);
  if(n==5){var a=moving||late?NewMilitaryAction.CancelRecallKnown:NewMilitaryAction.CancelRecallHome;Check(game.OffersMilitary(a),"normal cancellation option is available for this authored recall");if(moving){var input=new NewMilitaryInput(new("request:cancel-qa/"+s.Revision),a){TargetOriginal=OriginalCommand().Id,RequestedEffectiveAt=OriginalCommand().DueAt+3,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract,PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,DeliverBy=s.Seconds+600};Check(s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code==ResultCode.Accepted,"future effective cancellation uses same public decision API");game.Refresh();}else game.ChooseMilitary(a);Check(s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Effects.Length==0,"sending is not receipt or cancellation effect");}
  if(n==6){game.Advance(Math.Max(CurrentCancel().DueAt,OriginalCommand().DueAt));var x=s.DiagnosticSnapshot().NewMilitary!.Cancellation!;Check(moving?x.Effects.Length==0:late?x.Receives.Length==0:x.Effects.Single().Outcome==UnitCancelDisposition.Suppressed,"physical receipt and future effective boundary are separate");}
  if(n==7){if(moving){game.Advance(OriginalCommand().DueAt+2);Check(s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Effects.Length==0,"target continues before requested effective time");}else{var w=s.DiagnosticSnapshot();game.Advance(Math.Max(w.NewMilitary!.Withdrawal!.Receipts.Single().ReplyDueAt,w.NewMilitary.Cancellation!.Receipts.Single().ReplyDueAt));}}
  if(n==8){if(moving){game.Advance(OriginalCommand().DueAt+3);var w=s.DiagnosticSnapshot();Check(w.NewMilitary!.Cancellation!.Effects.Single().Outcome==UnitCancelDisposition.Stopped,"only remaining target movement stops at exact future boundary");Check(!NewGameMilitary.CancellationStatus(w).Contains("残りの移動を停止"),"remote result is not leaked before actual notice delivery");}else if(late)game.ChooseMilitary(NewMilitaryAction.DeliverHeldCancelHome);else game.ChooseMilitary(NewMilitaryAction.RetryRecallHome);}
  if(n==9){if(moving){var f=s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Notices.Single();game.Advance(Math.Max(s.Seconds,f.DueAt-1));}else if(late){game.Advance(s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);Check(s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Receives.Single().Late,"same retained cancellation arrives physically late");game.ChooseMilitary(NewMilitaryAction.DeliverHeldRecallHome);}else game.Advance(s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Dispatches.Last().DueAt);}
  if(n==10){if(moving){game.Advance(s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Notices.Single().DueAt);Check(NewGameMilitary.CancellationStatus(s.DiagnosticSnapshot()).Contains("残りの移動を停止"),"player learns exact result only on received physical notice");}else if(late)game.Advance(s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);var w=s.DiagnosticSnapshot();Check(w.NewMilitary!.Cancellation!.Effects.Length==1,"one cancellation effect across physical attempts");if(!moving)Check(!w.NewMilitary.Orders.Any(o=>o.Id.Value.StartsWith("order:unit-post/")),"cancelled original never executes through retry or late handover");}
  if(n==11){var w=s.DiagnosticSnapshot();long until=NewGameMilitary.UnitReceipts(w).Select(r=>r.ReplyDueAt).Concat(w.NewMilitary!.Cancellation!.Notices.Select(f=>f.DueAt)).Concat(w.NewMilitary.CommandHolding?.Outcomes.Select(f=>f.DueAt)??[]).DefaultIfEmpty(s.Seconds).Max();game.Advance(Math.Max(until,s.Seconds));}
  if(n==12&&moving)game.Advance(s.Seconds+2);
  if(n==13&&!moving){game.ChooseMilitary(NewMilitaryAction.Attach);game.ChooseMilitary(NewMilitaryAction.Reclaim);game.ChooseMilitary(NewMilitaryAction.Enter);game.ChooseMilitary(NewMilitaryAction.Unload);game.ChooseMilitary(NewMilitaryAction.Report);game.ChooseMilitary(NewMilitaryAction.Return);}
  if(n==14){game.Advance(s.Seconds+3);OpenAllServiceLetters();if(!moving)Check(s.DiagnosticSnapshot().NewMilitary!.Events.Any(e=>e.Effect==MilitaryEffect.Returned),"same person completes actual command and cargo handover after cancellation");game.Press("military-frame");}
  if(n==15){var w=s.DiagnosticSnapshot();if(moving)for(int i=0;i<3;i++)Check(NewGameMilitary.Position(w,i,s.Seconds)==w.NewMilitary!.Cancellation!.Effects.Single().Positions[i],"all stopped unit poses retain exact effective-time position");}
  game.Press("save");game.Refresh();
 }
 async Task BeginUnitCancelContinuation(){for(int n=1;n<=7;n++)await MilitaryStep(n);for(int n=0;n<UnitCancelCheckpoints;n++){await UnitCancelStep(n);game!.SaveCheckpoint("unitcancel"+n);await Capture("s"+n,true);}await Capture("final",true);}
 async Task RestoreUnitCancel(){Press("load-list");await Frame();string id=File.ReadAllText(Path.Combine(TestOutput,"campaign-instance.txt"));savedList.Select(Array.FindIndex(savedRows,r=>r.Profile.Instance==id));Press("load");await Frame();for(int n=0;n<UnitCancelCheckpoints;n++){game!.LoadCheckpoint("unitcancel"+n);await Frame();await Frame();Check(game.Pose()==File.ReadAllText(Path.Combine(TestOutput,"s"+n+"-pose.json")),"actual cancellation/person/unit/courier pose restored at"+n);await Capture("restored-s"+n,true);for(int next=n+1;next<UnitCancelCheckpoints;next++)await UnitCancelStep(next);Check(ContractJson.CanonicalHash(game.Session.DiagnosticSnapshot())==File.ReadAllText(Path.Combine(TestOutput,"final-world.sha256")),"same receipt/effect/physical-result future from"+n);await Capture("continued-s"+n,true);GD.Print("UNIT_CANCEL_RESTORED "+n);}}
 async Task RunUnitCancelChecks(){if(OS.GetCmdlineUserArgs().Contains("--new-game-restore"))await RestoreUnitCancel();else await BeginNewMilitaryFlow();if(OS.GetCmdlineUserArgs().Contains("--unit-cancel-film")){game!.LoadCheckpoint("unitcancel6");game.Press("auto");string dir=Path.Combine(TestOutput,"film");Directory.CreateDirectory(dir);for(int n=0;n<180;n++){await Frame();ViewportCapture.Save(GetViewport(),Path.Combine(dir,"cancel-"+n.ToString("D3")+".png"));}game.Press("pause");}File.WriteAllText(Path.Combine(TestOutput,OS.GetCmdlineUserArgs().Contains("--new-game-restore")?"restore-checks.json":"check-checks.json"),System.Text.Json.JsonSerializer.Serialize(assertions));GD.Print("UNIT_CANCEL_PASSED "+FlowCase);}
}
